from datetime import date, timedelta
from typing import Dict, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: Set[str] = set()
        # Maps book_id to (borrower_user, borrow_date)
        self.borrowed_books: Dict[str, tuple[str, date]] = {}
        # Maps user to the set of book_ids they currently hold
        self.user_loans: Dict[str, Set[str]] = {}
        # Maps user to their total accumulated unpaid fines
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in the library.")
        if book_id in self.borrowed_books:
            raise ValueError(f"Book '{book_id}' is already borrowed.")

        current_loans = self.user_loans.get(user, set())
        # A user with unpaid fines may hold at most one book at a time
        if self.unpaid_fines(user) > 0 and len(current_loans) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self.borrowed_books[book_id] = (user, day)
        current_loans.add(book_id)
        self.user_loans[user] = current_loans

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.borrowed_books or self.borrowed_books[book_id][0] != user:
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        _, borrow_date = self.borrowed_books.pop(book_id)
        self.user_loans[user].remove(book_id)

        due_date = borrow_date + timedelta(days=self.loan_days)
        delay_days = 0

        # Count weekdays between due_date + 1 and return day (inclusive)
        current = due_date + timedelta(days=1)
        while current <= day:
            # Monday is 0, Sunday is 6; exclude Saturday (5) and Sunday (6)
            if current.weekday() < 5:
                delay_days += 1
            current += timedelta(days=1)

        fine = delay_days * self.daily_fine
        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
