        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: set[str] = set()
        self.borrowed_books: dict[str, LoanRecord] = {}
        self.user_loans: defaultdict[str, set[str]] = defaultdict(set)
        self.fines: defaultdict[str, float] = defaultdict(float)

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in the library.")
        if book_id in self.borrowed_books:
            raise ValueError(f"Book '{book_id}' is already borrowed.")

        if self.unpaid_fines(user) > 0 and len(self.user_loans[user]) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self.borrowed_books[book_id] = LoanRecord(user=user, borrow_date=day)
        self.user_loans[user].add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        loan = self.borrowed_books.get(book_id)
        if loan is None or loan.user != user:
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        del self.borrowed_books[book_id]
        self.user_loans[user].remove(book_id)
        if not self.user_loans[user]:
            del self.user_loans[user]

        fine = self._calculate_fine(loan.borrow_date, day)
        if fine > 0:
            self.fines[user] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines.pop(user, None)

    def _calculate_fine(self, borrow_date: date, return_date: date) -> float:
        due_date = borrow_date + timedelta(days=self.loan_days)
        overdue_days = (return_date - due_date).days

        if overdue_days <= 0:
            return 0.0

        # Count overdue days excluding Saturday (5) and Sunday (6)
        weekdays_overdue = sum(
            1
            for offset in range(1, overdue_days + 1)
            if (due_date + timedelta(days=offset)).weekday() < 5
        )
        return weekdays_overdue * self.daily_fine
